/**
 * Which 3D model to draw for an aircraft: ICAO type designator → model, falling back to the model class.
 * The manifest is generated by `npm run data:models` and extended by `npm run models:import` (licensed models).
 */
import type { ModelClass } from './aircraftTypes';
import manifestJson from './aircraftModels.json';

export interface ModelEntry {
  /** Path under /models/. */
  file: string;
  /** Content hash, appended as ?v= so the files can be cached as immutable. */
  rev?: string;
  name: string;
  cls: ModelClass;
  /** Real dimensions, m. */
  length: number;
  span: number;
  height: number;
  /** Has the `_LIVERY` vertex attribute (tail/winglets painted in the operator's colour). */
  livery: boolean;
  /** Has a retractable "gear" node. */
  gear: boolean;
  /** Light positions in the model frame, [forward, left, up] metres (left-side lights are mirrored). */
  lights?: { tip: [number, number, number]; tail: [number, number, number]; top: [number, number, number]; belly: [number, number, number]; land: [number, number, number] };
  source: 'generated' | 'licensed';
  licence?: string;
  author?: string;
  url?: string;
  /** Airline ICAO code when this is an airline-specific replica. */
  airline?: string;
}

export interface ModelManifest {
  v: 1;
  models: Record<string, ModelEntry>;
  /** ICAO type designator → model. */
  types: Record<string, string>;
  classes: Record<ModelClass, string>;
  /** Airline-specific replicas (licensed livery models): airline ICAO code → type designator → model. */
  liveries?: Record<string, Record<string, string>>;
}

const manifest = manifestJson as unknown as ModelManifest;

/** Model for an aircraft: the operator's own replica of this type, else the type's model, else the class model. */
export function resolveModel(m: ModelManifest, type: string | undefined, cls: ModelClass, airline?: string): string {
  const t = type?.toUpperCase();
  const own = t && airline ? m.liveries?.[airline.toUpperCase()]?.[t] : undefined;
  const id = (own && m.models[own] && own) || (t && m.types[t]) || m.classes[cls] || m.classes.generic;
  return m.models[id] ? id : m.classes.generic;
}

export function modelIdFor(type: string | undefined, cls: ModelClass, airline?: string): string {
  return resolveModel(manifest, type, cls, airline);
}

export function modelEntry(id: string): ModelEntry {
  return manifest.models[id] ?? manifest.models[manifest.classes.generic];
}

/** URL of a model file (versioned by content hash). */
export function modelUrl(e: ModelEntry): string {
  return `/models/${e.file}${e.rev ? `?v=${e.rev}` : ''}`;
}

export function allModels(): Readonly<Record<string, ModelEntry>> {
  return manifest.models;
}
